  if (!value) return "기록 없음";
  return new Intl.DateTimeFormat(
    "ko-KR",
    withTime
      ? { dateStyle: "medium", timeStyle: "short" }
      : { dateStyle: "medium" },
  ).format(new Date(value));
}
